high_tech_bunker_core.source:
export const envelope = [24, 30, 24];

export default function build(api) {
  const { theme } = api;

  // Palette resolution from theme with high-tech / decayed modern fallbacks
  const stonePrimary = theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = theme?.stone?.accent || "minecraft:polished_andesite";
  const groundPlinth = theme?.ground?.plinth || "minecraft:deepslate_bricks";
  const groundPavement = theme?.ground?.pavement || "minecraft:smooth_stone";

  // Fast deterministic hash for organic weathering, cracks, and foliage
  function hash(x, y, z) {
    let h = (x * 374761393 + y * 668265263 + z * 982451653) ^ 0x5bf03635;
    h = (h ^ (h >>> 13)) * 1274126177;
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  }

  // Safe bounded block writer
  function set(x, y, z, block) {
    if (x >= 0 && x < 24 && y >= 0 && y < 30 && z >= 0 && z < 24) {
      api.set(x, y, z, block);
    }
  }

  // Material selectors for concrete decay and fortified plating
  function getConcreteBlock(x, y, z) {
    const r = hash(x, y, z);
    if (r < 0.38) return groundPavement;
    if (r < 0.62) return stonePrimary;
    if (r < 0.78) return "minecraft:cracked_stone_bricks";
    if (r < 0.88) return "minecraft:mossy_stone_bricks";
    if (r < 0.95) return stoneAccent;
    return "minecraft:andesite";
  }

  function getArmorBlock(x, y, z) {
    const r = hash(x, y, z);
    if (r < 0.48) return "minecraft:polished_deepslate";
    if (r < 0.76) return groundPlinth;
    if (r < 0.90) return "minecraft:smooth_basalt";
    return "minecraft:iron_block";
  }

  // =========================================================================
  // 1. TERRAIN ADAPTATION & FOUNDATION (Rule 6 - Follow the ground)
  // =========================================================================
  for (let x = 2; x <= 21; x++) {
    for (let z = 0; z <= 21; z++) {
      const inFootprint = (z >= 2 && x >= 2 && x <= 21) || (z < 2 && x >= 9 && x <= 14);
      if (!inFootprint) continue;

      const groundH = api.heightAt(x, z);
      if (groundH < 0) {
        for (let y = groundH; y < 0; y++) {
          const r = hash(x, y, z);
          const block = r < 0.55 ? groundPlinth
                      : r < 0.80 ? "minecraft:polished_deepslate"
                      : "minecraft:cracked_stone_bricks";
          set(x, y, z, block);
        }
      }
    }
  }

  // =========================================================================
  // 2. STRUCTURAL FLOORS & CEILINGS
  // =========================================================================
  // Base floor (y = 0)
  for (let x = 2; x <= 21; x++) {
    for (let z = 2; z <= 21; z++) {
      set(x, 0, z, getArmorBlock(x, 0, z));
    }
  }
  // Entrance approach threshold (z = 0..1, x = 9..14 at y = 0)
  for (let x = 9; x <= 14; x++) {
    set(x, 0, 0, "minecraft:polished_andesite");
    const isYellow = (x % 2 === 0);
    set(x, 0, 1, isYellow ? "minecraft:yellow_concrete" : "minecraft:black_concrete");
  }

  // Mid floor / Level 2 deck (y = 7)
  for (let x = 3; x <= 20; x++) {
    for (let z = 3; z <= 20; z++) {
      // Keep hole at ladder shaft (x = 18, z = 6)
      if (x === 18 && z === 6) continue;
      set(x, 7, z, getConcreteBlock(x, 7, z));
    }
  }

  // Sheared Roof Deck (y = 14) with apocalyptic collapse profile on SE corner
  for (let x = 3; x <= 20; x++) {
    for (let z = 3; z <= 20; z++) {
      if (x === 18 && z === 6) continue; // Hatch opening
      // Shear boundary: southeastern collapse
      if (x + z <= 33) {
        set(x, 14, z, getConcreteBlock(x, 14, z));
      } else if (x + z === 34 && hash(x, 14, z) < 0.5) {
        set(x, 14, z, "minecraft:cracked_stone_bricks");
      }
    }
  }

  // Dangling exposed structural steel I-beams over sheared roof void
  for (let z = 14; z <= 20; z++) {
    set(11, 14, z, "minecraft:polished_basalt[axis=z]");
    if (z > 17 && hash(11, 13, z) < 0.6) {
      set(11, 13, z, "minecraft:chain[axis=y]");
    }
  }
  for (let x = 14; x <= 20; x++) {
    set(x, 14, 11, "minecraft:polished_basalt[axis=x]");
    if (x > 17 && hash(x, 13, 11) < 0.6) {
      set(x, 13, 11, "minecraft:chain[axis=y]");
    }
  }

  // =========================================================================
  // 3. MAIN STRUCTURAL PILLARS (SKYSCRAPER SKELETON)
  // =========================================================================
  const pillars = [
    { minX: 3, maxX: 4, minZ: 3, maxZ: 4, topY: 24, rebarY: 27 },   // NW Pillar (tall)
    { minX: 19, maxX: 20, minZ: 3, maxZ: 4, topY: 23, rebarY: 24 }, // NE Pillar (antenna base)
    { minX: 3, maxX: 4, minZ: 19, maxZ: 20, topY: 19, rebarY: 22 }, // SW Pillar (broken)
    { minX: 19, maxX: 20, minZ: 19, maxZ: 20, topY: 16, rebarY: 18 }// SE Pillar (collapsed)
  ];

  for (const pil of pillars) {
    for (let x = pil.minX; x <= pil.maxX; x++) {
      for (let z = pil.minZ; z <= pil.maxZ; z++) {
        for (let y = 1; y <= pil.topY; y++) {
          if (y <= 7) {
            set(x, y, z, "minecraft:polished_deepslate");
          } else {
            set(x, y, z, getConcreteBlock(x, y, z));
          }
        }
        // Exposed rebar on top of sheared pillars
        for (let y = pil.topY + 1; y <= pil.rebarY; y++) {
          if (hash(x, y, z) < 0.75) {
            set(x, y, z, "minecraft:iron_bars");
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. FORTIFIED EXTERIOR WALLS & FACADES
  // =========================================================================
  // WEST WALL (x = 3..4, z = 3..20)
  for (let z = 3; z <= 20; z++) {
    for (let y = 1; y <= 14; y++) {
      // Lower blast armor (y = 1..6)
      if (y <= 6) {
        // Glowing tech conduit at z = 11..12
        if (z === 11 || z === 12) {
          set(4, y, z, "minecraft:polished_deepslate");
          set(3, y, z, (y % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");
          set(2, y, z, "minecraft:iron_bars");
        } else if (y === 3 && (z === 8 || z === 15)) {
          // Viewing slits
          set(4, y, z, "minecraft:tinted_glass");
          set(3, y, z, "minecraft:iron_bars");
        } else {
          set(4, y, z, getArmorBlock(4, y, z));
          set(3, y, z, getArmorBlock(3, y, z));
        }
      }
      // Upper ruined facade (y = 8..13)
      else if (y >= 8 && y <= 13) {
        if ((y === 9 || y === 10) && (z >= 7 && z <= 16 && z !== 11 && z !== 12)) {
          set(4, y, z, "minecraft:tinted_glass");
          set(3, y, z, (hash(3, y, z) < 0.4) ? "minecraft:iron_bars" : "minecraft:tinted_glass");
        } else {
          set(4, y, z, getConcreteBlock(4, y, z));
          set(3, y, z, getConcreteBlock(3, y, z));
        }
      }
    }
  }

  // EAST WALL (x = 19..20, z = 3..20)
  for (let z = 3; z <= 20; z++) {
    for (let y = 1; y <= 14; y++) {
      if (y <= 6) {
        if (z === 11 || z === 12) {
          set(19, y, z, "minecraft:polished_deepslate");
          set(20, y, z, (y % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:exposed_copper");
          set(21, y, z, "minecraft:iron_bars");
        } else if (y === 3 && (z === 8 || z === 15)) {
          set(19, y, z, "minecraft:tinted_glass");
          set(20, y, z, "minecraft:iron_bars");
        } else {
          set(19, y, z, getArmorBlock(19, y, z));
          set(20, y, z, getArmorBlock(20, y, z));
        }
      } else if (y >= 8 && y <= 13) {
        if ((y === 9 || y === 10) && (z >= 7 && z <= 16 && z !== 11 && z !== 12)) {
          set(19, y, z, "minecraft:tinted_glass");
          set(20, y, z, "minecraft:iron_bars");
        } else {
          set(19, y, z, getConcreteBlock(19, y, z));
          set(20, y, z, getConcreteBlock(20, y, z));
        }
      }
    }
  }

  // SOUTH WALL (z = 19..20, x = 3..20)
  for (let x = 3; x <= 20; x++) {
    for (let y = 1; y <= 14; y++) {
      if (y <= 6) {
        // Heavy generator exhaust grilles on rear
        if ((x >= 8 && x <= 10) || (x >= 13 && x <= 15)) {
          if (y === 2 || y === 3) {
            set(19, y, x, "minecraft:polished_deepslate");
            set(x, y, 20, "minecraft:iron_bars");
            set(x, y, 19, "minecraft:polished_basalt[axis=z]");
            continue;
          }
        }
        set(x, y, 19, getArmorBlock(x, y, 19));
        set(x, y, 20, getArmorBlock(x, y, 20));
      } else if (y >= 8 && y <= 13) {
        if ((y === 9 || y === 10) && x >= 7 && x <= 16) {
          set(x, y, 19, "minecraft:tinted_glass");
          set(x, y, 20, "minecraft:iron_bars");
        } else {
          set(x, y, 19, getConcreteBlock(x, y, 19));
          set(x, y, 20, getConcreteBlock(x, y, 20));
        }
      }
    }
  }

  // NORTH WALL & FLANKING FACADES (z = 3..4, x = 3..20 except center gate)
  for (let x = 3; x <= 20; x++) {
    if (x >= 10 && x <= 13) continue; // Entrance blast airlock gate
    for (let y = 1; y <= 14; y++) {
      if (y <= 6) {
        if (y === 3 && (x === 6 || x === 17)) {
          set(x, y, 4, "minecraft:tinted_glass");
          set(x, y, 3, "minecraft:iron_bars");
        } else if (x === 8 || x === 15) {
          // Warning vertical power conduits flanking entrance
          set(x, y, 4, "minecraft:polished_deepslate");
          set(x, y, 3, (y % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");
        } else {
          set(x, y, 4, getArmorBlock(x, y, 4));
          set(x, y, 3, getArmorBlock(x, y, 3));
        }
      } else if (y >= 8 && y <= 13) {
        if ((y === 9 || y === 10) && ((x >= 5 && x <= 8) || (x >= 15 && x <= 18))) {
          set(x, y, 4, "minecraft:tinted_glass");
          set(x, y, 3, "minecraft:iron_bars");
        } else {
          set(x, y, 4, getConcreteBlock(x, y, 4));
          set(x, y, 3, getConcreteBlock(x, y, 3));
        }
      }
    }
  }

  // Airlock partition wall at z = 5 (between entrance corridor and bunker hub)
  for (let x = 5; x <= 18; x++) {
    if (x === 11 || x === 12) continue; // Corridor opening
    for (let y = 1; y <= 6; y++) {
      set(x, y, 5, getArmorBlock(x, y, 5));
    }
  }

  // =========================================================================
  // 5. BLAST DOOR AIRLOCK ENTRANCE (-Z FACING, LOCAL NORTH)
  // =========================================================================
  // Portal Arch (z = 2, x = 9..14)
  for (let y = 1; y <= 5; y++) {
    const isYEven = (y % 2 === 0);
    // Left & right hazard jambs
    set(9, y, 2, isYEven ? "minecraft:yellow_concrete" : "minecraft:polished_blackstone");
    set(14, y, 2, isYEven ? "minecraft:yellow_concrete" : "minecraft:polished_blackstone");
    set(9, y, 1, "minecraft:polished_deepslate");
    set(14, y, 1, "minecraft:polished_deepslate");
  }
  // Top overhead hazard lintel (y = 5, z = 2)
  for (let x = 9; x <= 14; x++) {
    const isXEven = (x % 2 === 0);
    set(x, 5, 2, isXEven ? "minecraft:yellow_concrete" : "minecraft:polished_blackstone");
  }
  // Warning floodlights above gate
  set(11, 5, 1, "minecraft:sea_lantern");
  set(12, 5, 1, "minecraft:sea_lantern");
  set(11, 6, 2, "minecraft:lightning_rod[facing=north]");
  set(12, 6, 2, "minecraft:lightning_rod[facing=north]");

  // Recessed blast doors & side bulkheads (z = 3..4)
  for (let z = 3; z <= 4; z++) {
    for (let y = 1; y <= 4; y++) {
      set(10, y, z, "minecraft:iron_block");
      set(13, y, z, "minecraft:iron_block");
    }
    // Overhead heavy blast shutter plate
    set(11, 4, z, "minecraft:iron_block");
    set(12, 4, z, "minecraft:iron_block");
  }
  // Sensor unit at top of vestibule
  set(11, 5, 3, "minecraft:polished_basalt[axis=y]");
  set(12, 5, 3, "minecraft:polished_basalt[axis=y]");
  set(11, 5, 4, "minecraft:sea_lantern");
  set(12, 5, 4, "minecraft:sea_lantern");

  // Vestibule corridor floor (y = 0, z = 2..5, x = 11..12)
  for (let z = 2; z <= 5; z++) {
    set(11, 0, z, "minecraft:smooth_stone");
    set(12, 0, z, "minecraft:smooth_stone");
  }

  // =========================================================================
  // 6. VERTICAL CIRCULATION SHAFT (LADDER CORE AT x = 18, z = 6)
  // =========================================================================
  // Structural enclosure around ladder
  for (let y = 1; y <= 14; y++) {
    set(18, y, 5, "minecraft:polished_deepslate");
    set(18, y, 7, "minecraft:polished_deepslate");
    set(19, y, 6, "minecraft:polished_deepslate");
    // Climbing ladder attached to north backing block
    set(18, y, 6, "minecraft:ladder[facing=south]");
  }
  // Roof exit trapdoor
  set(18, 14, 6, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");

  // =========================================================================
  // 7. ROOF DECK HIGH-TECH RETROFITS (y = 14 to 29)
  // =========================================================================
  // Parapet safety walls around surviving roof deck
  for (let x = 3; x <= 17; x++) {
    if (hash(x, 15, 3) < 0.8) set(x, 15, 3, "minecraft:stone_brick_wall");
  }
  for (let z = 3; z <= 17; z++) {
    if (hash(3, 15, z) < 0.8) set(3, 15, z, "minecraft:stone_brick_wall");
  }

  // --- SATELLITE UPLINK RADAR DISH (x = 7..10, z = 8..11, y = 15..19) ---
  // Heavy swivel base pedestal
  set(8, 15, 9, "minecraft:iron_block");
  set(9, 15, 9, "minecraft:iron_block");
  set(8, 15, 10, "minecraft:smooth_basalt");
  set(9, 15, 10, "minecraft:smooth_basalt");
  set(8, 16, 9, "minecraft:polished_andesite");
  set(9, 16, 9, "minecraft:polished_andesite");

  // Parabolic dish structure angled towards south sky
  for (let x = 7; x <= 10; x++) {
    set(x, 16, 8, "minecraft:quartz_stairs[facing=south,half=bottom]");
    set(x, 17, 9, "minecraft:smooth_quartz");
    set(x, 18, 10, "minecraft:quartz_stairs[facing=north,half=top]");
    set(x, 19, 11, "minecraft:quartz_slab[type=bottom]");
  }
  // Parabolic dish side wings
  set(6, 17, 9, "minecraft:quartz_stairs[facing=east,half=bottom]");
  set(11, 17, 9, "minecraft:quartz_stairs[facing=west,half=bottom]");
  // Central feed horn arm
  set(8, 17, 10, "minecraft:polished_deepslate");
  set(9, 17, 10, "minecraft:polished_deepslate");
  set(8, 17, 11, "minecraft:lightning_rod[facing=south]");
  set(9, 17, 11, "minecraft:lightning_rod[facing=south]");

  // --- SOLAR PANEL ARRAY (x = 13..16, z = 9..12) ---
  for (let x = 13; x <= 16; x++) {
    for (let z = 9; z <= 12; z++) {
      set(x, 15, z, "minecraft:iron_bars");
      set(x, 16, z, "minecraft:daylight_detector");
    }
  }
  // Copper power feed busline
  for (let z = 8; z <= 12; z++) {
    set(12, 15, z, "minecraft:exposed_copper");
  }

  // --- HEAVY GENERATOR & AIR SCRUBBER (x = 5..8, z = 13..16, y = 15..17) ---
  for (let x = 5; x <= 8; x++) {
    for (let z = 13; z <= 16; z++) {
      set(x, 15, z, "minecraft:polished_basalt[axis=y]");
      set(x, 16, z, (x === 6 || x === 7) ? "minecraft:iron_block" : "minecraft:chiseled_deepslate");
    }
  }
  // Exhaust chimney hoppers & fan grates
  set(6, 17, 14, "minecraft:hopper[facing=down]");
  set(7, 17, 14, "minecraft:hopper[facing=down]");
  set(5, 16, 14, "minecraft:iron_bars");
  set(8, 16, 14, "minecraft:iron_bars");

  // --- COMMS RELAY MAST TOWER (Atop NE Pillar, y = 24 to 29) ---
  for (let y = 24; y <= 27; y++) {
    set(19, y, 4, "minecraft:iron_bars");
  }
  // Red warning beacon & top antenna rod
  set(19, 28, 4, "minecraft:sea_lantern");
  set(19, 29, 4, "minecraft:lightning_rod[facing=up]");

  // =========================================================================
  // 8. JUNGLE OVERGROWTH & APOCALYPTIC DECAY
  // =========================================================================
  // Massive strangler root wrapping the NW pillar
  const rootPoints = [
    [2, 1, 3], [2, 2, 3], [2, 3, 4], [2, 4, 4],
    [3, 5, 5], [3, 6, 5], [4, 7, 5], [4, 8, 5],
    [5, 9, 4], [5, 10, 3], [4, 11, 2], [3, 12, 2],
    [2, 13, 3], [2, 14, 4], [2, 15, 4], [3, 16, 5]
  ];
  for (const [rx, ry, rz] of rootPoints) {
    set(rx, ry, rz, "minecraft:jungle_wood[axis=y]");
    // Leaf clumps surrounding the root
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (Math.abs(dx) + Math.abs(dz) === 1 && hash(rx + dx, ry, rz + dz) < 0.6) {
          set(rx + dx, ry, rz + dz, "minecraft:jungle_leaves[persistent=true,distance=1]");
        }
      }
    }
  }

  // Cascading foliage over sheared edges
  for (let x = 3; x <= 20; x++) {
    for (let z = 3; z <= 20; z++) {
      if (x + z >= 31 && x + z <= 34) {
        if (hash(x, 15, z) < 0.45) {
          set(x, 15, z, "minecraft:jungle_leaves[persistent=true,distance=1]");
          if (hash(x, 14, z) < 0.35) {
            set(x, 13, z, "minecraft:jungle_leaves[persistent=true,distance=1]");
          }
        }
      }
    }
  }

  // Creeping wall vines attached to outer concrete facades
  // West facade (x = 2, attached to x = 3)
  for (let z = 3; z <= 20; z++) {
    for (let y = 1; y <= 20; y++) {
      if (hash(2, y, z) < 0.28) {
        set(2, y, z, "minecraft:vine[east=true]");
      }
    }
  }
  // East facade (x = 21, attached to x = 20)
  for (let z = 3; z <= 20; z++) {
    for (let y = 1; y <= 15; y++) {
      if (hash(21, y, z) < 0.28) {
        set(21, y, z, "minecraft:vine[west=true]");
      }
    }
  }
  // South facade (z = 21, attached to z = 20)
  for (let x = 3; x <= 20; x++) {
    for (let y = 1; y <= 15; y++) {
      if (hash(x, y, 21) < 0.28) {
        set(x, y, 21, "minecraft:vine[north=true]");
      }
    }
  }
  // North facade (z = 2, attached to z = 3)
  for (let x = 3; x <= 20; x++) {
    if (x >= 9 && x <= 14) continue; // Keep entrance clear
    for (let y = 1; y <= 20; y++) {
      if (hash(x, y, 2) < 0.28) {
        set(x, y, 2, "minecraft:vine[south=true]");
      }
    }
  }

  // =========================================================================
  // 9. RETURN STRUCTURE DECLARATION
  // =========================================================================
  return {
    name: "High-Tech Bunker Core",
    seatY: 0,
    anchors: {
      front: [12, 1, 0],
      door: [12, 1, 2]
    },
    interiors: [
      // Level 1: Reinforced Survival Bunker / Command Hub
      { min: [5, 1, 6], max: [17, 6, 17], kind: "bunker" },
      // Level 2: High-Tech Laboratory & Comms Uplink Operations
      { min: [5, 8, 6], max: [17, 13, 17], kind: "laboratory" }
    ]
  };
}

collapsed_highway_span.source:
export const envelope = [32, 22, 14];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;

  // 3D Voxel Grid
  const grid = [];
  for (let x = 0; x < W; x++) {
    grid[x] = [];
    for (let y = 0; y < H; y++) {
      grid[x][y] = new Array(D).fill(null);
    }
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // Palette selection from theme with thematic fallbacks
  const stonePrim = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAcc = api.theme.stone?.accent || "minecraft:cracked_stone_bricks";
  const stoneSlab = api.theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";
  const asphalt = api.theme.ground?.pavement || "minecraft:gray_concrete";
  const kerb = api.theme.ground?.kerb || "minecraft:polished_andesite";
  const plinth = api.theme.ground?.plinth || "minecraft:smooth_stone";
  const revetment = api.theme.ground?.revetment || "minecraft:deepslate";
  const woodPlanks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log || "minecraft:spruce_log";
  const woodFence = api.theme.wood?.fence || "minecraft:spruce_fence";
  const woodSlab = api.theme.wood?.slab || "minecraft:spruce_slab";
  const woodStairs = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  // Specialized apocalyptic / overgrown materials
  const moss = "minecraft:moss_block";
  const mossCarpet = "minecraft:moss_carpet";
  const crackedStone = "minecraft:cracked_stone_bricks";
  const mossyStone = "minecraft:mossy_stone_bricks";
  const deepslate = "minecraft:polished_deepslate";
  const deepslateWall = "minecraft:polished_deepslate_wall";
  const ironBars = "minecraft:iron_bars";
  const chain = "minecraft:chain";
  const lanternHang = "minecraft:lantern[hanging=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";
  const oakLeaves = "minecraft:oak_leaves[persistent=true]";
  const azaleaLeaves = "minecraft:flowering_azalea_leaves[persistent=true]";
  const yellowLine = "minecraft:yellow_concrete";
  const lightRod = "minecraft:lightning_rod[facing=up]";
  const solarPanel = "minecraft:daylight_detector";
  const scaffold = "minecraft:scaffolding";
  const barrel = "minecraft:barrel";
  const cauldron = "minecraft:cauldron";

  function concreteNoise() {
    const r = api.random();
    if (r < 0.45) return stonePrim;
    if (r < 0.70) return crackedStone;
    if (r < 0.88) return mossyStone;
    return stoneAcc;
  }

  function asphaltNoise() {
    const r = api.random();
    if (r < 0.65) return asphalt;
    if (r < 0.85) return crackedStone;
    return moss;
  }

  // -------------------------------------------------------------
  // 1. HIGH ELEVATED SPAN (Intact section: X = 0 to 9)
  // -------------------------------------------------------------
  const deckSurfaceY = seatY + 10; // Y = 16

  // Reinforced concrete pillars (Piers under high deck)
  for (let y = seatY; y <= seatY + 8; y++) {
    for (let x = 2; x <= 4; x++) {
      for (let z = 2; z <= 4; z++) {
        set(x, y, z, (y === seatY || y === seatY + 8) ? deepslate : concreteNoise());
      }
      for (let z = 9; z <= 11; z++) {
        set(x, y, z, (y === seatY || y === seatY + 8) ? deepslate : concreteNoise());
      }
    }
  }

  // Cross girder between piers
  for (let z = 2; z <= 11; z++) {
    set(3, seatY + 7, z, deepslate);
    set(3, seatY + 8, z, concreteNoise());
  }

  // Longitudinal underside I-beams
  for (let x = 0; x <= 9; x++) {
    for (const z of [2, 6, 7, 11]) {
      set(x, deckSurfaceY - 2, z, deepslate);
    }
  }

  // Concrete deck slab (Y = deckSurfaceY - 1 = 15)
  for (let x = 0; x <= 9; x++) {
    for (let z = 1; z <= 12; z++) {
      // Jagged fracture break at X = 9
      if (x === 9 && (z === 4 || z === 8 || z === 9)) continue;
      set(x, deckSurfaceY - 1, z, concreteNoise());
    }
  }

  // Upper road surface (Y = deckSurfaceY = 16)
  for (let x = 0; x <= 9; x++) {
    for (let z = 2; z <= 11; z++) {
      if (x === 9 && (z <= 4 || z >= 8)) continue;
      // Center dividing line
      if ((z === 6 || z === 7) && (x % 3 !== 0)) {
        set(x, deckSurfaceY, z, yellowLine);
      } else {
        set(x, deckSurfaceY, z, asphaltNoise());
      }
    }
  }

  // Parapets and guardrails on intact deck
  for (let x = 0; x <= 8; x++) {
    // North rail
    set(x, deckSurfaceY + 1, 1, deepslateWall);
    if (x % 2 === 0) set(x, deckSurfaceY + 2, 1, ironBars);
    // South rail
    set(x, deckSurfaceY + 1, 12, deepslateWall);
    if (x % 2 === 0) set(x, deckSurfaceY + 2, 12, ironBars);
  }

  // -------------------------------------------------------------
  // 2. FORTIFIED HIDEOUT / BUNKER UNDER UPPER DECK
  // -------------------------------------------------------------
  // Shell walls around interior volume [2..7, seatY+1..seatY+4, 3..10]
  // Floor at seatY
  for (let x = 1; x <= 8; x++) {
    for (let z = 2; z <= 11; z++) {
      set(x, seatY, z, deepslate);
    }
  }

  // Bunker ceiling / structural divider at seatY + 5
  for (let x = 1; x <= 8; x++) {
    for (let z = 2; z <= 11; z++) {
      set(x, seatY + 5, z, concreteNoise());
    }
  }

  // West Wall (X = 1)
  for (let y = seatY + 1; y <= seatY + 4; y++) {
    for (let z = 2; z <= 11; z++) {
      if (y === seatY + 2 && (z === 6 || z === 7)) {
        set(1, y, z, ironBars);
      } else {
        set(1, y, z, concreteNoise());
      }
    }
  }

  // North Wall (Z = 2) & South Wall (Z = 11)
  for (let y = seatY + 1; y <= seatY + 4; y++) {
    for (let x = 1; x <= 8; x++) {
      // North
      if (y === seatY + 2 && x === 6) set(x, y, 2, ironBars);
      else set(x, y, 2, concreteNoise());
      // South
      if (y === seatY + 2 && x === 6) set(x, y, 11, ironBars);
      else set(x, y, 11, concreteNoise());
    }
  }

  // East Wall (X = 8) with fortified entrance at Z = 6, 7
  for (let y = seatY + 1; y <= seatY + 4; y++) {
    for (let z = 2; z <= 11; z++) {
      if ((z === 6 || z === 7) && (y === seatY + 1 || y === seatY + 2)) {
        // Doorway left open
        continue;
      } else if (y === seatY + 3 && (z === 4 || z === 9)) {
        set(8, y, z, ironBars);
      } else {
        set(8, y, z, concreteNoise());
      }
    }
  }

  // Doorway frame reinforcement
  set(8, seatY + 1, 5, deepslateWall);
  set(8, seatY + 2, 5, deepslateWall);
  set(8, seatY + 1, 8, deepslateWall);
  set(8, seatY + 2, 8, deepslateWall);
  set(8, seatY + 3, 6, deepslate);
  set(8, seatY + 3, 7, deepslate);
  set(9, seatY + 3, 6, lanternHang);

  // Exterior ladder / scaffold access from bunker door up to high deck
  for (let y = seatY + 1; y <= deckSurfaceY; y++) {
    set(8, y, 4, scaffold);
  }

  // -------------------------------------------------------------
  // 3. UPPER DECK APOCALYPTIC FIT-OUT & OBSERVATION POST
  // -------------------------------------------------------------
  // Barricade across fractured edge at X = 8
  for (let z = 2; z <= 11; z++) {
    if (z === 6 || z === 7) continue; // catwalk gap
    set(8, deckSurfaceY + 1, z, (z % 2 === 0) ? stoneWall : deepslate);
    if (z === 3 || z === 10) set(8, deckSurfaceY + 2, z, ironBars);
  }

  // Sniper / Observation Nest at [X = 5..7, Z = 2..4]
  set(5, deckSurfaceY + 1, 2, woodFence);
  set(5, deckSurfaceY + 2, 2, woodFence);
  set(7, deckSurfaceY + 1, 2, woodFence);
  set(7, deckSurfaceY + 2, 2, woodFence);
  set(5, deckSurfaceY + 1, 4, woodFence);
  set(5, deckSurfaceY + 2, 4, woodFence);
  set(7, deckSurfaceY + 1, 4, woodFence);
  set(7, deckSurfaceY + 2, 4, woodFence);

  for (let x = 5; x <= 7; x++) {
    for (let z = 2; z <= 4; z++) {
      set(x, deckSurfaceY + 3, z, (api.random() < 0.6) ? woodSlab : oakLeaves);
    }
  }
  set(6, deckSurfaceY + 2, 3, lanternHang);

  // Comms Antenna Mast at [X = 2, Z = 2]
  set(2, deckSurfaceY + 1, 2, plinth);
  set(2, deckSurfaceY + 2, 2, ironBars);
  set(2, deckSurfaceY + 3, 2, ironBars);
  set(2, deckSurfaceY + 4, 2, lightRod);

  // Solar Panel Array at [X = 2..3, Z = 9..10]
  for (let x = 2; x <= 3; x++) {
    for (let z = 9; z <= 10; z++) {
      set(x, deckSurfaceY + 1, z, plinth);
      set(x, deckSurfaceY + 2, z, solarPanel);
    }
  }

  // Makeshift salvage crane extending over fracture
  set(7, deckSurfaceY + 3, 6, woodLog);
  set(8, deckSurfaceY + 3, 6, woodLog);
  set(9, deckSurfaceY + 3, 6, woodLog);
  set(10, deckSurfaceY + 3, 6, ironBars);
  set(10, deckSurfaceY + 2, 6, chain);
  set(10, deckSurfaceY + 1, 6, chain);
  set(10, deckSurfaceY, 6, cauldron);

  // -------------------------------------------------------------
  // 4. FRACTURE CHASM & SUSPENSION CATWALK (X = 8 to 13)
  // -------------------------------------------------------------
  // Exposed twisted rebar sticking out from high deck break
  set(10, deckSurfaceY - 1, 3, ironBars);
  set(11, deckSurfaceY - 1, 3, ironBars);
  set(10, deckSurfaceY - 1, 10, ironBars);
  set(11, deckSurfaceY - 1, 10, ironBars);

  // Hanging severed cables
  for (let y = deckSurfaceY - 4; y <= deckSurfaceY - 2; y++) {
    set(9, y, 2, chain);
    set(9, y, 11, chain);
  }

  // Wooden suspension bridge spanning the gap (X = 8 to 13, Z = 6, 7)
  for (let x = 8; x <= 13; x++) {
    const bridgeY = (x >= 12) ? deckSurfaceY - 1 : deckSurfaceY;
    set(x, bridgeY, 6, woodPlanks);
    set(x, bridgeY, 7, woodPlanks);

    if (x >= 9 && x <= 12) {
      set(x, bridgeY + 1, 5, woodFence);
      set(x, bridgeY + 1, 8, woodFence);
    }
  }
  set(10, deckSurfaceY + 2, 5, lanternFloor);
  set(11, deckSurfaceY + 2, 8, lanternFloor);

  // -------------------------------------------------------------
  // 5. COLLAPSED / SLOPING HIGHWAY SPAN (X = 13 to 28)
  // -------------------------------------------------------------
  for (let x = 13; x <= 27; x++) {
    const t = (x - 13) / 14;
    // Deck descends from Y=15 down to Y=6 (seatY)
    const dy = Math.round(9 * (1 - t));
    const curY = seatY + dy;

    for (let z = 1; z <= 12; z++) {
      // Dynamic tilt: north edge slightly lower at points
      const tilt = (z <= 3 && x % 2 === 0) ? -1 : 0;
      const yDeck = curY + tilt;

      // Road deck undercarriage
      set(x, yDeck - 1, z, concreteNoise());

      // Underside longitudinal beams
      if (z === 2 || z === 6 || z === 7 || z === 11) {
        set(x, yDeck - 2, z, deepslate);
      }

      // Road surface
      const isStairStep = (x > 13 && Math.round(9 * (1 - (x - 14) / 14)) < Math.round(9 * (1 - (x - 13) / 14)));
      if (isStairStep && (z >= 4 && z <= 9)) {
        set(x, yDeck, z, "minecraft:stone_brick_stairs[facing=east,half=bottom]");
      } else {
        set(x, yDeck, z, asphaltNoise());
      }

      // Overgrowth patches on collapsed slab
      if (api.random() < 0.18 && yDeck + 1 < H) {
        set(x, yDeck + 1, z, mossCarpet);
      }

      // Broken parapets along the sides
      if (z === 1 || z === 12) {
        // Gaps where rails broke off during impact
        if (!((x >= 16 && x <= 18) || (x >= 23 && x <= 24))) {
          set(x, yDeck + 1, z, (api.random() < 0.6) ? stoneWall : deepslateWall);
        }
      }
    }
  }

  // Mid-slope Guard Barricade / Observation Shelter at X = 20, 21
  const checkY = seatY + Math.round(9 * (1 - (20 - 13) / 14)); // Y ~ 10
  for (let z = 2; z <= 11; z++) {
    if (z === 6 || z === 7) continue; // walkway gap
    set(20, checkY + 1, z, deepslateWall);
  }
  // Watch canopy on south side of slope
  set(20, checkY + 1, 10, woodFence);
  set(20, checkY + 2, 10, woodFence);
  set(21, checkY + 1, 10, woodFence);
  set(21, checkY + 2, 10, woodFence);
  set(20, checkY + 1, 12, woodFence);
  set(20, checkY + 2, 12, woodFence);
  set(21, checkY + 1, 12, woodFence);
  set(21, checkY + 2, 12, woodFence);

  for (let x = 20; x <= 21; x++) {
    for (let z = 10; z <= 12; z++) {
      set(x, checkY + 3, z, (api.random() < 0.5) ? woodSlab : azaleaLeaves);
    }
  }
  set(20, checkY + 2, 11, lanternHang);

  // -------------------------------------------------------------
  // 6. STREET-LEVEL IMPACT ZONE & RUBBLE FIELD (X = 27 to 31)
  // -------------------------------------------------------------
  for (let x = 27; x <= 31; x++) {
    for (let z = 1; z <= 12; z++) {
      const dist = (x - 27);
      const r = api.random();
      if (dist === 0) {
        set(x, seatY + 1, z, concreteNoise());
        set(x, seatY, z, deepslate);
      } else if (dist === 1) {
        if (r < 0.6) set(x, seatY + 1, z, "minecraft:stone_brick_slab[type=bottom]");
        set(x, seatY, z, concreteNoise());
      } else {
        if (r < 0.35) {
          set(x, seatY + 1, z, (r < 0.15) ? stoneWall : mossCarpet);
        }
        set(x, seatY, z, (r < 0.5) ? asphaltNoise() : concreteNoise());
      }
    }
  }

  // Smashed concrete barrier chunks & twisted rebar in rubble
  set(29, seatY + 1, 2, deepslateWall);
  set(30, seatY + 1, 3, stoneWall);
  set(30, seatY + 1, 10, ironBars);
  set(31, seatY + 1, 11, stoneWall);
  set(28, seatY + 1, 8, ironBars);

  // Supply barrels near bunker entrance at ground level
  set(9, seatY + 1, 4, barrel);
  set(9, seatY + 1, 5, barrel);
  set(9, seatY + 2, 4, barrel);

  // -------------------------------------------------------------
  // 7. OVERGROWTH, FOLIAGE & VINES
  // -------------------------------------------------------------
  // Foliage clusters hanging from high deck edges
  for (let x = 0; x <= 8; x += 2) {
    set(x, deckSurfaceY, 0, (api.random() < 0.5) ? oakLeaves : azaleaLeaves);
    set(x, deckSurfaceY - 1, 0, oakLeaves);
    set(x, deckSurfaceY, 13, (api.random() < 0.5) ? oakLeaves : azaleaLeaves);
    set(x, deckSurfaceY - 1, 13, oakLeaves);
  }

  // Hanging vines / roots under broken span
  for (let x = 14; x <= 22; x += 3) {
    const dy = Math.round(9 * (1 - (x - 13) / 14));
    const yDeck = seatY + dy;
    set(x, yDeck - 3, 1, oakLeaves);
    set(x, yDeck - 3, 12, oakLeaves);
  }

  // -------------------------------------------------------------
  // 8. GROUND BASE & FOUNDATION CONFORMANCE (Rules 5 & 6)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(H - 1, seatY + Math.round(h)));

      // Find lowest occupied voxel in structure for this column
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          minY = y;
          break;
        }
      }

      if (minY !== -1) {
        // Structure occupies this column: fill down to terrain
        if (minY > groundY) {
          for (let y = minY - 1; y >= groundY; y--) {
            const r = api.random();
            let fBlock;
            if (r < 0.45) fBlock = revetment;
            else if (r < 0.75) fBlock = stonePrim;
            else if (r < 0.90) fBlock = stoneAcc;
            else fBlock = plinth;
            set(x, y, z, fBlock);
          }
        }
      } else {
        // Lay ground street boulevard and fill to ground
        if (groundY <= seatY) {
          for (let y = groundY; y <= seatY; y++) {
            const r = api.random();
            let gBlock;
            if (y === seatY) {
              gBlock = (r < 0.6) ? asphalt : ((r < 0.8) ? crackedStone : moss);
            } else {
              gBlock = (r < 0.5) ? revetment : stonePrim;
            }
            set(x, y, z, gBlock);
          }
        }
      }

      // If terrain rises above seat plane outside bunker, conform upward
      const inBunker = (x >= 2 && x <= 7 && z >= 3 && z <= 10);
      if (!inBunker && groundY > seatY) {
        for (let y = seatY; y <= groundY; y++) {
          if (get(x, y, z) === null) {
            set(x, y, z, (api.random() < 0.5) ? stoneAcc : moss);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 9. EMIT BLOCKS TO API
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "collapsed_highway_span",
    seatY: seatY,
    anchors: {
      front: [8, seatY + 1, 0],
      door: [8, seatY + 1, 6],
      lookout: [6, deckSurfaceY + 1, 3],
    },
    interiors: [
      {
        min: [2, seatY + 1, 3],
        max: [7, seatY + 4, 10],
        kind: "quarters",
      },
    ],
  };
}

surveillance_relay_mast.source:
export const envelope = [9, 24, 9];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const seatY = 5;

  const rawIdx = api.instance && typeof api.instance.index === "number" ? api.instance.index : 0;
  const instIdx = ((rawIdx % 8) + 8) % 8;

  function rng() {
    return api.random();
  }

  // Theme palette extraction
  const stonePrim = (api.theme && api.theme.stone && api.theme.stone.primary) ? api.theme.stone.primary : "minecraft:smooth_stone";
  const stoneAcc = (api.theme && api.theme.stone && api.theme.stone.accent) ? api.theme.stone.accent : "minecraft:polished_andesite";
  const stoneWall = (api.theme && api.theme.stone && api.theme.stone.wall) ? api.theme.stone.wall : "minecraft:stone_brick_wall";
  const stoneSlab = (api.theme && api.theme.stone && api.theme.stone.slab) ? api.theme.stone.slab : "minecraft:smooth_stone_slab";
  const plinth = (api.theme && api.theme.ground && api.theme.ground.plinth) ? api.theme.ground.plinth : stonePrim;
  const fence = (api.theme && api.theme.wood && api.theme.wood.fence) ? api.theme.wood.fence : "minecraft:dark_oak_fence";

  // Flat 3D array for voxels
  const voxelGrid = new Array(W * H * D);
  for (let i = 0; i < voxelGrid.length; i++) {
    voxelGrid[i] = null;
  }

  function getIdx(x, y, z) {
    return x + W * (y + H * z);
  }

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      voxelGrid[getIdx(x, y, z)] = block;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return voxelGrid[getIdx(x, y, z)];
    }
    return null;
  }

  // -------------------------------------------------------------------------
  // 1. RUINED CONCRETE ROOFTOP PYLON / BASE (Ground-conforming)
  // -------------------------------------------------------------------------
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const dx = x - 4;
      const dz = z - 4;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist <= 3.3) {
        const rawH = api.heightAt(x, z);
        const groundH = Math.round(rawH);
        const groundY = Math.max(0, Math.min(seatY, seatY + groundH));

        let topY = 7;
        if (x === 4 && z === 4) {
          topY = 9;
        } else if (Math.abs(dx) <= 1 && Math.abs(dz) <= 1) {
          topY = 8;
        } else if (dist <= 2.3) {
          topY = 7;
        } else {
          topY = 6;
        }

        // Concrete weathering degradation
        if ((x !== 4 || z !== 4) && rng() < 0.2) {
          topY -= 1;
        }

        // Fill solid base down to ground
        for (let y = groundY; y <= topY; y++) {
          if (y < seatY) {
            setVoxel(x, y, z, plinth);
          } else {
            const r = rng();
            if ((instIdx % 2 === 1 || instIdx === 5) && r < 0.35) {
              setVoxel(x, y, z, r < 0.18 ? "minecraft:moss_block" : "minecraft:mossy_stone_bricks");
            } else if (r < 0.5) {
              setVoxel(x, y, z, stoneAcc);
            } else {
              setVoxel(x, y, z, stonePrim);
            }
          }
        }

        // Rusty protruding rebar
        if (topY < 7 && rng() < 0.35) {
          const rebarLen = 1 + Math.floor(rng() * 2);
          for (let ry = 1; ry <= rebarLen; ry++) {
            setVoxel(x, topY + ry, z, "minecraft:iron_bars");
          }
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. EQUIPMENT BATTERY CORE & ACCESS LADDER
  // -------------------------------------------------------------------------
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      setVoxel(x, 7, z, stonePrim);
      setVoxel(x, 8, z, stoneAcc);
    }
  }
  setVoxel(4, 9, 4, "minecraft:lodestone");

  // Auxiliary avionics / junction units
  setVoxel(5, 7, 4, "minecraft:observer[facing=east]");
  setVoxel(5, 8, 4, "minecraft:daylight_detector");
  setVoxel(3, 7, 4, "minecraft:observer[facing=west]");
  setVoxel(3, 8, 4, "minecraft:daylight_detector");
  setVoxel(4, 7, 5, "minecraft:target");
  setVoxel(4, 8, 5, "minecraft:redstone_lamp");

  // Access ladder on North pylon face
  for (let y = seatY; y <= 8; y++) {
    setVoxel(4, y, 3, "minecraft:ladder[facing=north]");
  }

  // -------------------------------------------------------------------------
  // 3. MAST STRUCTURE & PROCEDURAL SURVEILLANCE PAYLOAD
  // -------------------------------------------------------------------------
  if (instIdx === 0) {
    // Parabolic Deep-Space Comms Dish
    for (let y = 9; y <= 17; y++) {
      setVoxel(4, y, 4, stoneWall);
    }
    setVoxel(4, 18, 4, "minecraft:lodestone");
    setVoxel(4, 19, 4, "minecraft:lightning_rod[facing=up]");
    setVoxel(4, 20, 4, "minecraft:lightning_rod[facing=up]");
    setVoxel(4, 21, 4, "minecraft:end_rod[facing=up]");

    for (let x = 1; x <= 7; x++) {
      setVoxel(x, 12, 4, "minecraft:iron_bars");
    }
    setVoxel(1, 13, 4, "minecraft:daylight_detector");
    setVoxel(2, 13, 4, "minecraft:daylight_detector");
    setVoxel(6, 13, 4, "minecraft:daylight_detector");
    setVoxel(7, 13, 4, "minecraft:daylight_detector");

    setVoxel(4, 15, 4, stoneAcc);
    setVoxel(4, 15, 3, "minecraft:hopper[facing=south]");
    setVoxel(4, 15, 2, "minecraft:lightning_rod[facing=north]");

    setVoxel(4, 16, 3, "minecraft:smooth_quartz_stairs[facing=south,half=bottom]");
    setVoxel(4, 14, 3, "minecraft:smooth_quartz_stairs[facing=south,half=top]");
    setVoxel(3, 15, 3, "minecraft:smooth_quartz_stairs[facing=east,half=bottom]");
    setVoxel(5, 15, 3, "minecraft:smooth_quartz_stairs[facing=west,half=bottom]");
    setVoxel(3, 16, 3, "minecraft:smooth_quartz_slab");
    setVoxel(5, 16, 3, "minecraft:smooth_quartz_slab");
    setVoxel(3, 14, 3, "minecraft:smooth_quartz_slab");
    setVoxel(5, 14, 3, "minecraft:smooth_quartz_slab");

    setVoxel(3, 15, 4, "minecraft:iron_bars");
    setVoxel(5, 15, 4, "minecraft:iron_bars");
    setVoxel(4, 16, 4, "minecraft:iron_bars");
    setVoxel(4, 14, 4, "minecraft:iron_bars");

    for (let y = 7; y <= 11; y++) {
      setVoxel(2, y, 4, "minecraft:chain[axis=y]");
