          if (getVoxel(x, y, z + 1) !== null && rng() < 0.25) {
            setVoxel(x, y, z, "minecraft:vine[south=true]");
          } else if (getVoxel(x, y, z - 1) !== null && rng() < 0.25) {
            setVoxel(x, y, z, "minecraft:vine[north=true]");
          } else if (getVoxel(x + 1, y, z) !== null && rng() < 0.25) {
            setVoxel(x, y, z, "minecraft:vine[east=true]");
