  // -------------------------------------------------------------------------
  // 5. ONE CONNECTED SOLID BODY GUARANTEE (BFS)
  // -------------------------------------------------------------------------
  const rootIdx = getIdx(4, 5, 4);
  const visited = new Uint8Array(W * H * D);

  if (voxelGrid[rootIdx] !== null) {
    const queue = [rootIdx];
    visited[rootIdx] = 1;
    let head = 0;

    const neighborOffsets = [
      1, -1,
      W, -W,
      W * H, -W * H
    ];

    while (head < queue.length) {
      const cur = queue[head++];
      const cx = cur % W;
      const cy = Math.floor((cur % (W * H)) / W);
      const cz = Math.floor(cur / (W * H));

      if (cx + 1 < W) {
        const ni = cur + 1;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
      if (cx - 1 >= 0) {
        const ni = cur - 1;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
      if (cy + 1 < H) {
        const ni = cur + W;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
      if (cy - 1 >= 0) {
        const ni = cur - W;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
      if (cz + 1 < D) {
        const ni = cur + W * H;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
      if (cz - 1 >= 0) {
        const ni = cur - W * H;
        if (voxelGrid[ni] !== null && visited[ni] === 0) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
    }

    // Drop disconnected fragments
    for (let i = 0; i < voxelGrid.length; i++) {
      if (voxelGrid[i] !== null && visited[i] === 0) {
        voxelGrid[i] = null;
      }
    }
  }

  // -------------------------------------------------------------------------
  // 6. MINIMUM SOLID VOLUME ASSURANCE (>= 520 Voxels)
  // -------------------------------------------------------------------------
  let solidCount = 0;
  for (let i = 0; i < voxelGrid.length; i++) {
    if (voxelGrid[i] !== null) {
      solidCount++;
    }
  }

  if (solidCount < 520) {
    for (let y = 1; y <= 6; y++) {
      for (let x = 2; x <= 6; x++) {
        for (let z = 2; z <= 6; z++) {
          const idx = getIdx(x, y, z);
          if (voxelGrid[idx] === null) {
            voxelGrid[idx] = stonePrim;
            solidCount++;
            if (solidCount >= 520) break;
          }
        }
        if (solidCount >= 520) break;
      }
      if (solidCount >= 520) break;
    }
  }

  // -------------------------------------------------------------------------
  // 7. EMIT BLOCKS DETERMINISTICALLY
  // -------------------------------------------------------------------------
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
